arguments.file_text:
@page "/settings"
@using sv_faf5822caeca4490987c59ec98582ed8.Models
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => ActiveSection = section.Key">
                        <span class="section-icon">@section.Value.Icon</span>
                        @section.Value.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastMessage is not null)
        {
            <div class="toast-notification @(_toastFading ? "fade-out" : "")">
                <span>✓</span> @_toastMessage
            </div>
        }

        @if (_showRevokeDialog)
        {
            <div class="modal-backdrop show"></div>
            <div class="modal d-block" tabindex="-1">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                            @if (_sessionToRevoke is not null)
                            {
                                <p class="text-muted mb-0">
                                    <strong>@_sessionToRevoke.Device</strong> — @_sessionToRevoke.Location
                                </p>
                            }
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastFading;
    private CancellationTokenSource? _toastCts;

    // Profile
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notifications
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = [];
    private HashSet<string> _mutedChannels = [];

    // Security
    private SecuritySettings? _security;
    private bool _twoFactorEnabled;
    private bool _showChangePassword;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _availableLanguages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    private record SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;

        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _allChannels = [.. notif.MutedChannels];
        _mutedChannels = [.. notif.MutedChannels];

        _security = securityTask.Result;
        _twoFactorEnabled = _security.TwoFactorEnabled;

        var appearance = appearanceTask.Result;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private async Task ShowToast(string message)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastFading = false;
        StateHasChanged();

        try
        {
            await Task.Delay(2500, token);
            _toastFading = true;
            StateHasChanged();
            await Task.Delay(500, token);
        }
        catch (TaskCanceledException) { }

        if (!token.IsCancellationRequested)
        {
            _toastMessage = null;
            _toastFading = false;
        }
    }

    // --- Profile ---
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is null) return;
        _displayName = _savedProfile.DisplayName;
        _email = _savedProfile.Email;
        _avatarUrl = _savedProfile.AvatarUrl;
        _bio = _savedProfile.Bio;
    }

    // --- Notifications ---
    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // --- Security ---
    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _showChangePassword = false;
        _security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeDialog = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // --- Appearance ---
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewBackground => _theme switch
    {
        "Dark" => "#1e1e2e",
        _ => "#ffffff"
    };

    private string PreviewText => _theme switch
    {
        "Dark" => "#cdd6f4",
        _ => "#1a1a2e"
    };

    // --- Render fragments ---
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h3 class="section-title">Profile</h3>
        <p class="text-muted">Manage your personal information and public profile.</p>

        <div class="card settings-card">
            <div class="card-body">
                <div class="avatar-area mb-4">
                    <div class="avatar-preview">
                        @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                        {
                            <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">👤</div>
                        }
                    </div>
                    <div class="avatar-url-field flex-grow-1">
                        <label class="form-label">Avatar URL</label>
                        <input type="url" class="form-control" @bind="_avatarUrl" placeholder="https://example.com/avatar.png" />
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="_displayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="3" @bind="_bio"></textarea>
                </div>

                <div class="d-flex gap-2">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h3 class="section-title">Notifications</h3>
        <p class="text-muted">Choose how you want to be notified.</p>

        <div class="card settings-card">
            <div class="card-body">
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                    <label class="form-check-label" for="emailNotif">
                        <strong>Email Notifications</strong>
                        <small class="d-block text-muted">Receive updates via email</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                    <label class="form-check-label" for="pushNotif">
                        <strong>Push Notifications</strong>
                        <small class="d-block text-muted">Browser and mobile push alerts</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-4">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">
                        <strong>Weekly Digest</strong>
                        <small class="d-block text-muted">Summary of activity sent every Monday</small>
                    </label>
                </div>

                <hr />

                <h6 class="mb-3">Channel Muting</h6>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var isMuted = _mutedChannels.Contains(channel);
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="ch-@channel"
                                   checked="@isMuted"
                                   @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                            <label class="form-check-label" for="ch-@channel">#@channel</label>
                        </div>
                    }
                </div>

                <button class="btn btn-primary mt-3" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h3 class="section-title">Security</h3>
        <p class="text-muted">Manage your password, two-factor authentication, and active sessions.</p>

        <!-- Change Password -->
        <div class="card settings-card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor: pointer;" @onclick="() => _showChangePassword = !_showChangePassword">
                <strong>Change Password</strong>
                <span>@(_showChangePassword ? "▲" : "▼")</span>
            </div>
            @if (_showChangePassword)
            {
                <div class="card-body">
                    @if (_passwordError is not null)
                    {
                        <div class="alert alert-danger py-2">@_passwordError</div>
                    }

                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor -->
        <div class="card settings-card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <div class="mt-1">
                        @if (_twoFactorEnabled)
                        {
                            <span class="badge bg-success">Enabled</span>
                        }
                        else
                        {
                            <span class="badge bg-secondary">Disabled</span>
                        }
                    </div>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card settings-card">
            <div class="card-header"><strong>Active Sessions</strong></div>
            <div class="card-body p-0">
                @if (_security?.Sessions is { Count: > 0 })
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _security.Sessions)
                                {
                                    var isCurrentSession = session == _security.Sessions[0];
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isCurrentSession)
                                            {
                                                <span class="badge bg-info ms-1">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@FormatTimeAgo(session.LastActive)</td>
                                        <td>
                                            @if (!isCurrentSession)
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => RequestRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
                else
                {
                    <p class="p-3 text-muted mb-0">No active sessions.</p>
                }
            </div>
        </div>

        @if (_security?.LastPasswordChange is not null)
        {
            <p class="text-muted mt-3 small">
                Last password change: @_security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
            </p>
        }
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h3 class="section-title">Appearance</h3>
        <p class="text-muted">Customize how the application looks and feels.</p>

        <div class="card settings-card mb-3">
            <div class="card-body">
                <h6>Theme</h6>
                <div class="d-flex gap-3 mb-4">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                                   value="@theme" checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="theme-@theme">@theme</label>
                        </div>
                    }
                </div>

                <h6>Font Size</h6>
                <div class="d-flex gap-3 mb-4">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                                   value="@size" checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="fs-@size">@size</label>
                        </div>
                    }
                </div>

                <h6>Language</h6>
                <div class="mb-4">
                    <select class="form-select" style="max-width: 250px;" @bind="_language">
                        @foreach (var lang in _availableLanguages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <div class="form-check form-switch mb-4">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">
                        <strong>Compact Mode</strong>
                        <small class="d-block text-muted">Reduce spacing and padding throughout the UI</small>
                    </label>
                </div>

                <hr />

                <h6>Live Preview</h6>
                <div class="preview-box" style="background-color: @PreviewBackground; color: @PreviewText; font-size: @PreviewFontSize; padding: @(_compactMode ? "0.5rem" : "1rem");">
                    <h6 style="color: @PreviewText; margin-bottom: @(_compactMode ? "0.25rem" : "0.5rem");">Preview Title</h6>
                    <p style="margin-bottom: @(_compactMode ? "0.25rem" : "0.75rem");">
                        This is how your content will look with the selected settings.
                        The theme is <strong>@_theme</strong>, font size is <strong>@_fontSize</strong>,
                        and compact mode is <strong>@(_compactMode ? "on" : "off")</strong>.
                    </p>
                    <button class="btn btn-sm @(_theme == "Dark" ? "btn-outline-light" : "btn-outline-dark")">
                        Sample Button
                    </button>
                </div>

                <button class="btn btn-primary mt-3" @onclick="SaveAppearance">Save</button>
            </div>
        </div>
    };

    private static string FormatTimeAgo(DateTime dt)
    {
        var span = DateTime.UtcNow - dt;
        if (span.TotalMinutes < 1) return "Just now";
        if (span.TotalMinutes < 60) return $"{(int)span.TotalMinutes}m ago";
        if (span.TotalHours < 24) return $"{(int)span.TotalHours}h ago";
        return $"{(int)span.TotalDays}d ago";
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
    margin: -1.1rem -1.5rem;
}

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

